import base64

import numpy as np
import pytest
import ujson
import xarray as xr
from hypothesis import given, settings, strategies as st
from obspec_utils.registry import ObjectStoreRegistry
from obstore.store import LocalStore

from virtualizarr.parsers import KerchunkJSONParser, KerchunkParquetParser
from virtualizarr.parsers.kerchunk.translator import manifest_from_kerchunk_chunk_dict
from virtualizarr.xarray import open_virtual_dataset

pytest.importorskip("kerchunk")


def _registry():
    return ObjectStoreRegistry({"file://": LocalStore()})


def _data_of(manifest, key="0"):
    return manifest.dict()[key]["data"]


def test_plain_inlined_string_is_utf8_encoded():
    """An inlined chunk string without a 'base64:' prefix is stored in the manifest as its UTF-8 bytes."""
    m = manifest_from_kerchunk_chunk_dict({"0": "hello wörld"}, shape=(1,))
    assert _data_of(m) == "hello wörld".encode("utf-8")


def test_base64_prefixed_inlined_string_is_decoded():
    """An inlined chunk string starting with 'base64:' is base64-decoded into the manifest bytes."""
    raw = bytes(range(256))
    s = "base64:" + base64.b64encode(raw).decode()
    m = manifest_from_kerchunk_chunk_dict({"0": s}, shape=(1,))
    assert _data_of(m) == raw


def test_inlined_chunk_does_not_raise_not_implemented():
    """Reading kerchunk chunk references with inlined data no longer raises NotImplementedError."""
    manifest_from_kerchunk_chunk_dict({"0": "abc"}, shape=(1,))


def test_mixed_inlined_and_referenced_chunks():
    """Inlined chunks and path-based chunks can live side by side in one manifest."""
    m = manifest_from_kerchunk_chunk_dict(
        {"0": "abc", "1": ["file:///tmp/a.nc", 10, 20]}, shape=(2,)
    )
    d = m.dict()
    assert d["0"]["data"] == b"abc"
    assert d["1"]["path"] == "file:///tmp/a.nc"
    assert d["1"]["offset"] == 10
    assert d["1"]["length"] == 20


@settings(max_examples=50)
@given(st.binary(max_size=200))
def test_base64_roundtrip_any_bytes(raw):
    """For any bytes, a 'base64:'-prefixed encoding of them is read back as exactly those bytes."""
    s = "base64:" + base64.b64encode(raw).decode()
    m = manifest_from_kerchunk_chunk_dict({"0": s}, shape=(1,))
    assert _data_of(m) == raw


@settings(max_examples=50)
@given(st.text(max_size=100).filter(lambda s: not s.startswith("base64:")))
def test_plain_string_is_its_utf8_bytes_for_any_text(text):
    """For any string not starting with 'base64:', the manifest holds its UTF-8 encoding."""
    try:
        text.encode("utf-8")
    except UnicodeEncodeError:
        return
    m = manifest_from_kerchunk_chunk_dict({"0": text}, shape=(1,))
    assert _data_of(m) == text.encode("utf-8")


def _inlined_ref(tmp_path):
    from kerchunk.hdf import SingleHdf5ToZarr

    nc = tmp_path / "f.nc"
    ds = xr.Dataset(
        {"a": (("x",), np.arange(5, dtype="float32"))},
        coords={"x": np.arange(5)},
    )
    ds.to_netcdf(nc, engine="h5netcdf")
    return SingleHdf5ToZarr(str(nc), inline_threshold=1000).translate()


def _inlined_chunk_values(ref):
    out = {}
    for k, v in ref["refs"].items():
        if isinstance(v, str) and not k.split("/")[-1].startswith("."):
            out[k] = v
    return out


def _decode(v):
    if v.startswith("base64:"):
        return base64.b64decode(v[len("base64:"):])
    return v.encode("utf-8")


def test_json_reference_with_inlined_data_opens_and_keeps_bytes(tmp_path):
    """Opening a kerchunk JSON file containing inlined data succeeds and the inlined bytes appear in the manifests."""
    ref = _inlined_ref(tmp_path)
    inlined = _inlined_chunk_values(ref)
    assert inlined
    path = tmp_path / "ref.json"
    path.write_text(ujson.dumps(ref))
    with open_virtual_dataset(
        url=path.as_posix(), registry=_registry(), parser=KerchunkJSONParser()
    ) as vds:
        found = []
        for name, var in vds.variables.items():
            manifest = getattr(var.data, "manifest", None)
            if manifest is None:
                continue
            for entry in manifest.dict().values():
                if entry.get("data") is not None:
                    found.append(entry["data"])
        expected = {_decode(v) for k, v in inlined.items() if "/" in k}
        assert expected
        assert expected <= set(found)


def test_parquet_reference_with_inlined_data_opens_and_keeps_bytes(tmp_path):
    """Opening a kerchunk Parquet reference containing inlined data succeeds and the inlined bytes appear in the manifests."""
    pytest.importorskip("fastparquet")
    import pandas as pd
    from kerchunk.df import refs_to_dataframe

    ref = _inlined_ref(tmp_path)
    inlined = _inlined_chunk_values(ref)
    path = tmp_path / "ref.parquet"
    with pd.option_context("future.infer_string", False):
        refs_to_dataframe(fo=ref, url=path.as_posix())
    with open_virtual_dataset(
        url=path.as_posix(), registry=_registry(), parser=KerchunkParquetParser()
    ) as vds:
        found = []
        for var in vds.variables.values():
            manifest = getattr(var.data, "manifest", None)
            if manifest is None:
                continue
            for entry in manifest.dict().values():
                if entry.get("data") is not None:
                    found.append(entry["data"])
        expected = {_decode(v) for k, v in inlined.items() if "/" in k}
        assert expected
        assert expected <= set(found)

